-- Forward provider policy contracts. Local synthetic identities; every row rolls back.
begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create temp table sandbox_state(key text primary key,value jsonb);
create function pg_temp.sb_actor(a uuid) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true)::text is not null$$;
create function pg_temp.sb_cmd(slug text,cmd text,body jsonb default '{}') returns jsonb language sql as $$select api.frightnight_command(slug,cmd,body,gen_random_uuid())$$;
create function pg_temp.sb_arm(p_slug text,p_actor uuid) returns jsonb language sql as $$select api.frightnight_contract_arm(p_slug,p_actor,f.run_id,'nocteiuvohesvqbowchw:staging:duindorphalloweenstg:'||p_slug||':'||f.run_id)from app_private.fn_events f join app_private.events e on e.id=f.event_id where e.slug=p_slug$$;
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data)select ('f7330000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'sandbox-'||n||'@example.invalid',now(),'{}','{}'from generate_series(1,5)n;
insert into app_private.events(id,slug,title,local_date,price_cents)values('f7330000-0000-0000-0000-000000000010','sandbox-local-legacy','Local synthetic policy sentinel','2026-10-31',350);
insert into app_private.event_capabilities(event_id,user_id,capability)values('f7330000-0000-0000-0000-000000000010','f7330000-0000-0000-0000-000000000001','event_admin');
select api.frightnight_bootstrap(s,'f7330000-0000-0000-0000-000000000001','staging','nocteiuvohesvqbowchw:staging:duindorphalloweenstg')is not null from unnest(array['frightnight-2027-test','frightnight-2027-test-sandbox-a','frightnight-2027-test-sandbox-b','frightnight-2027-test-sandbox-c'])s;
insert into sandbox_state values('protected',jsonb_build_object('outbox',(select count(*)from app_private.email_outbox),'payments',(select count(*)from app_private.payment_requests),'groups',(select count(*)from app_private.walking_groups),'auth',(select count(*)from auth.users)));
select ok(not has_function_privilege('authenticated','api.frightnight_contract_arm(text,uuid,uuid,text)','EXECUTE'),'browser cannot arm a contract sandbox');
select ok(not has_function_privilege('service_role','api.frightnight_payment_create(text,uuid,uuid)','EXECUTE'),'legacy fixture creation bridge is owner-only, not a default provider service path');
select ok(not has_function_privilege('service_role','api.frightnight_payment_test_order(text,uuid,uuid,uuid)','EXECUTE'),'legacy fixture simulation bridge is owner-only, not a mode bypass');
select ok(not has_function_privilege('anon','api.frightnight_payment_claim(text,uuid,uuid,text)','EXECUTE'),'anonymous client cannot select an order provider');
select ok(has_function_privilege('service_role','api.frightnight_payment_claim(text,uuid,uuid,text)','EXECUTE'),'trusted server may atomically claim configured provider');
select ok(not has_function_privilege('service_role','app_private.fn_payment_provider(uuid,text)','EXECUTE'),'service has no direct private resolver grant');
select throws_ok($$select pg_temp.sb_arm('frightnight-2027-test','f7330000-0000-0000-0000-000000000001')$$,'42501','CANONICAL_SANDBOX_FORBIDDEN','canonical edition cannot be armed even by its event administrator');
select throws_ok($$select pg_temp.sb_arm('frightnight-2027-test-sandbox-a','f7330000-0000-0000-0000-000000000002')$$,'42501','EDITION_ACCESS_REQUIRED','foreign actor cannot arm a private edition');
select pg_temp.sb_actor('f7330000-0000-0000-0000-000000000001');
select is(api.frightnight_snapshot('frightnight-2027-test-sandbox-a')#>>'{paymentSandbox,reason}',null::text,'fresh private run reports eligibility server-side');
select is(api.frightnight_snapshot('frightnight-2027-test-sandbox-a')#>>'{event,paymentPolicy}','configured','fresh copies follow server configuration by default');
select throws_ok($$select api.frightnight_contract_arm('frightnight-2027-test-sandbox-a','f7330000-0000-0000-0000-000000000001',gen_random_uuid(),'wrong')$$,'40001','SANDBOX_RUN_CONFLICT','stale or foreign run cannot be armed');
select throws_ok($$select api.frightnight_contract_arm('frightnight-2027-test-sandbox-a','f7330000-0000-0000-0000-000000000001',(select run_id from app_private.fn_events f join app_private.events e on e.id=f.event_id where e.slug='frightnight-2027-test-sandbox-a'),'wrong')$$,'22023','SANDBOX_CONFIRMATION_REQUIRED','full infrastructure and edition binding is mandatory');
select lives_ok($$select pg_temp.sb_arm('frightnight-2027-test-sandbox-a','f7330000-0000-0000-0000-000000000001')$$,'fresh own child can be explicitly armed');
select lives_ok($$select pg_temp.sb_arm('frightnight-2027-test-sandbox-a','f7330000-0000-0000-0000-000000000001')$$,'same-run arm retry is idempotent');
select is((select count(*)from app_private.fn_audit where action='payment.sandbox_armed'),1::bigint,'idempotent arming writes one audit record');
select is(api.frightnight_snapshot('frightnight-2027-test-sandbox-a')#>>'{event,contractSandboxArmed}','true','server readback proves current run is armed');
select pg_temp.sb_cmd('frightnight-2027-test-sandbox-a','test.seed');
insert into sandbox_state select 'contract',api.frightnight_payment_test_claim('frightnight-2027-test-sandbox-a','f7330000-0000-0000-0000-000000000001',(select r.id from app_private.fn_registrations r join app_private.events e on e.id=r.event_id where e.slug='frightnight-2027-test-sandbox-a'limit 1),'f7330000-0000-0000-0000-000000000101','mollie');
select is((select value->>'provider'from sandbox_state where key='contract'),'contract','armed child resolves contract despite global Mollie configuration');
select is((select value->>'provider_claimed'from sandbox_state where key='contract'),'true','provider is durable before any provider request');
select throws_ok($$update app_private.fn_orders set provider='mollie'where id=(select(value->>'order_id')::uuid from sandbox_state where key='contract')$$,'40001','ORDER_PROVIDER_IMMUTABLE','provider cannot change after first atomic claim');
select throws_ok($$select api.frightnight_payment_bind('frightnight-2027-test-sandbox-a',(select(value->>'order_id')::uuid from sandbox_state where key='contract'),'tr_Foreign123',null)$$,'22023','INVALID_PAYMENT_BINDING','a contract order cannot bind a Mollie payment');
select lives_ok($$select api.frightnight_payment_bind('frightnight-2027-test-sandbox-a',(select(value->>'order_id')::uuid from sandbox_state where key='contract'),'ct_'||(select value->>'order_id'from sandbox_state where key='contract'),null)$$,'contract reference binds only after provider claim');
select is(api.frightnight_payment_lookup('frightnight-2027-test-sandbox-a','ct_'||(select value->>'order_id'from sandbox_state where key='contract'))->>'provider','contract','provider lookup retains immutable contract binding');
select pg_temp.sb_cmd('frightnight-2027-test-sandbox-a','test.reset',jsonb_build_object('confirmation','frightnight-2027-test-sandbox-a','runId',(select run_id from app_private.fn_events f join app_private.events e on e.id=f.event_id where e.slug='frightnight-2027-test-sandbox-a')));
select is(api.frightnight_snapshot('frightnight-2027-test-sandbox-a')#>>'{event,contractSandboxArmed}','false','reset invalidates previous run arming without deleting payment history');
select throws_ok($$select api.frightnight_payment_test_claim('frightnight-2027-test-sandbox-a','f7330000-0000-0000-0000-000000000001',(select(value->>'registration_id')::uuid from sandbox_state where key='contract'),gen_random_uuid(),'mollie')$$,'40001','SANDBOX_REARM_REQUIRED','stale sandbox refuses provider fallback after reset');
select lives_ok($$select pg_temp.sb_arm('frightnight-2027-test-sandbox-a','f7330000-0000-0000-0000-000000000001')$$,'new empty run can be rearmed while preserving earlier contract history');
select is((select count(*)from app_private.fn_orders where id=(select(value->>'order_id')::uuid from sandbox_state where key='contract')),1::bigint,'rearming never deletes old contract orders');
-- A configured Mollie claim is persisted before its first external POST.
select api.frightnight_entry_grant('frightnight-2027-test-sandbox-b','f7330000-0000-0000-0000-000000000002',clock_timestamp()+interval'1 hour',repeat('a',64));
select pg_temp.sb_actor('f7330000-0000-0000-0000-000000000002');
select pg_temp.sb_cmd('frightnight-2027-test-sandbox-b','registration.save','{"label":"Synthetic Mollie quote","routeType":"lantern","adults":1,"children":1,"maxIntensity":1,"consent":true,"termsVersion":"2027-test-v1","startSlot":"2027-10-30T15:00Z"}');
select ok(not(api.frightnight_snapshot('frightnight-2027-test-sandbox-b')?'paymentSandbox'),'participant never sees test administrator counts or arming controls');
insert into sandbox_state select 'mollie',api.frightnight_payment_claim('frightnight-2027-test-sandbox-b','f7330000-0000-0000-0000-000000000002','f7330000-0000-0000-0000-000000000102','mollie');
select is((select value->>'provider'from sandbox_state where key='mollie'),'mollie','configured canonical policy can choose real test provider');
select is((select value->>'provider_claimed'from sandbox_state where key='mollie'),'true','Mollie claim is durable before external effect');
select is(api.frightnight_payment_claim('frightnight-2027-test-sandbox-b','f7330000-0000-0000-0000-000000000002','f7330000-0000-0000-0000-000000000102','contract')->>'provider','mollie','retry after environment change retains its persisted Mollie provider');
select throws_ok($$select api.frightnight_payment_bind('frightnight-2027-test-sandbox-b',(select(value->>'order_id')::uuid from sandbox_state where key='mollie'),'ct_'||(select value->>'order_id'from sandbox_state where key='mollie'),null)$$,'22023','INVALID_PAYMENT_BINDING','Mollie claim cannot be rebound as contract');
select lives_ok($$select api.frightnight_payment_bind('frightnight-2027-test-sandbox-b',(select(value->>'order_id')::uuid from sandbox_state where key='mollie'),'tr_Sandbox123','https://www.mollie.com/checkout/Sandbox123')$$,'Mollie binding preserves actual test provider');
select throws_ok($$select pg_temp.sb_arm('frightnight-2027-test-sandbox-b','f7330000-0000-0000-0000-000000000001')$$,'42501','MOLLIE_HISTORY_FORBIDDEN','any historical Mollie claim forbids sandbox arming');
select throws_ok($$select api.frightnight_payment_test_claim('frightnight-2027-test-sandbox-b','f7330000-0000-0000-0000-000000000001',(select(value->>'registration_id')::uuid from sandbox_state where key='mollie'),gen_random_uuid(),'mollie')$$,'42501','CONTRACT_ONLY','Mollie configured edition cannot use test-status simulator');
select pg_temp.sb_actor('f7330000-0000-0000-0000-000000000001');
select pg_temp.sb_cmd('frightnight-2027-test-sandbox-c','test.seed');
select throws_ok($$select pg_temp.sb_arm('frightnight-2027-test-sandbox-c','f7330000-0000-0000-0000-000000000001')$$,'42501','FRESH_RUN_REQUIRED','a seeded run cannot switch provider policy');
select is((select count(*)from app_private.email_outbox),(select(value->>'outbox')::bigint from sandbox_state where key='protected'),'sandbox operations leave legacy outbox unchanged');
select is((select count(*)from app_private.payment_requests),(select(value->>'payments')::bigint from sandbox_state where key='protected'),'sandbox operations leave historical payments unchanged');
select is((select count(*)from app_private.walking_groups),(select(value->>'groups')::bigint from sandbox_state where key='protected'),'sandbox operations never invoke legacy route groups');
select is((select count(*)from auth.users),(select(value->>'auth')::bigint from sandbox_state where key='protected'),'arming and payment claims never create or remove Auth accounts');
select *from finish();
rollback;
